/// <summary>
/// PricingAttribute of table <c>CustTable</c> field SubsegmentId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, SubSegmentId))]
internal class GUPPricingAttributeCustTableSubsegmentId extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, SubsegmentId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    Custtable                custTable;
    smmBusRelSubSegmentGroup    smmBusRelSubSegmentGroup;

    while select SubsegmentId from custtable
        join smmBusRelSubSegmentGroup
        group by SubsegmentId, Segmentid, SubSegmentDescription
        where custTable.SubsegmentId == smmBusRelSubSegmentGroup.SubsegmentId
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(smmBusRelSubSegmentGroup.SubsegmentId, smmBusRelSubSegmentGroup.SubSegmentDescription);
        ret.add(valueObject);
    }
    return ret;
}
